pm.test("User A Authenticated", function () {
    pm.response.to.have.status(201);
    // Giả lập lưu token của User A (UserId = 1)
    pm.collectionVariables.set("attacker_token", "Bearer token-user-1-abc");
    pm.collectionVariables.set("attacker_id", 1);
});

pm.test("Resource belongs to another user (Victim)", function () {
    pm.response.to.have.status(200);
    const data = pm.response.json();
    // Lưu ID bài viết của nạn nhân
    pm.collectionVariables.set("victim_post_id", data.id);
    pm.collectionVariables.set("victim_user_id", data.userId);

    // Kiểm tra chắc chắn tài nguyên này không phải của User A
    // Assuming attacker_id should be different from the resource's userId for this test to pass
    pm.expect(data.userId).to.not.eql(parseInt(pm.collectionVariables.get("attacker_id")));
});

pm.test("Security Gate: System must strip or reject unauthorized privilege escalation fields", function () {
    const res = pm.response.json();

    // Kiểm tra các trường nhạy cảm không được phép tồn tại trong dữ liệu lưu trữ
    pm.expect(res).to.not.have.property("role", "admin");
    pm.expect(res).to.not.have.property("is_admin", true);
    pm.expect(res).to.not.have.property("balance");
});

pm.test("Security Gate: Server must reject forged/tampered tokens with 401 Unauthorized", function () {
    // Hệ thống an toàn bắt buộc phải từ chối token không hợp lệ bằng mã 401
    pm.expect(pm.response.code).to.eql(401);
});

pm.test("Security Gate: Server must reject requests missing Authorization header with 401 Unauthorized", function () {
    // Hệ thống an toàn bắt buộc phải từ chối truy cập và trả về mã HTTP 401
    pm.expect(pm.response.code).to.eql(401);
});

pm.test("Security Gate: System must safely handle SQL injection payloads", function () {
    // 1. Máy chủ không được văng lỗi hệ thống 500 Internal Server Error
    pm.expect(pm.response.code).to.not.eql(500);

    // 2. Không được để lộ thông tin nhạy cảm hoặc từ khóa lỗi của Database
    const responseBody = pm.response.text().toLowerCase();
    const dangerousSignatures = [
        "syntax error", 
        "sqlite3::", 
        "psycopg2", 
        "sql syntax", 
        "mysql_fetch", 
        "ora-", 
        "unclosed quotation mark"
    ];

    dangerousSignatures.forEach(signature => {
        pm.expect(responseBody).to.not.include(signature);
    });
});

// 1. Kiểm tra rò rỉ công nghệ Backend (Server Fingerprinting)
pm.test("Security Gate: Server must not expose backend technology via X-Powered-By", function () {
    pm.expect(pm.response.headers.has("X-Powered-By")).to.be.false;
});

// 2. Kiểm tra header chống đánh hơi loại nội dung (MIME Sniffing)
pm.test("Security Gate: System should include X-Content-Type-Options: nosniff", function () {
    pm.expect(pm.response.headers.get("X-Content-Type-Options")).to.eql("nosniff");
});

if (!pm.variables.get("request_count")) {
    pm.variables.set("request_count", 1);
}
let count = Number(pm.variables.get("request_count"));
const maxAttempts = 15; // Thử nghiệm gửi 15 request dồn dập

pm.test(`Attempt ${count}: System should enforce Rate Limiting (HTTP 429)`, function () {
    if (count >= 10) {
        // Từ request thứ 10 trở đi, kỳ vọng server phải chặn lại bằng mã 429
        pm.expect(pm.response.code).to.eql(429);
    } else {
        // Các request ban đầu được phép thành công
        pm.expect(pm.response.code).to.be.oneOf([200, 201]);
    }
});

// Tự động lặp lại chính request này cho đến khi đủ số lượng
if (count < maxAttempts) {
    pm.variables.set("request_count", count + 1);
    postman.setNextRequest("Security - Rate Limit Bypass Check");
} else {
    pm.variables.unset("request_count");
    postman.setNextRequest(null); // Dừng chuỗi test
}
